// Reviewed against the current Angular components and ClothingAPI implementation.
const scenarios=[];
const m=(a,b,t)=>({k:'m',a,b,t}),r=(a,b,t)=>({k:'r',a,b,t}),c=t=>m(3,3,t),note=t=>({k:'note',t}),ref=t=>({k:'ref',t});
const start=(kind,t)=>({k:'start',kind,t}),end=()=>({k:'end'}),other=t=>({k:'else',t});
const db=(query,result='Dữ liệu truy vấn',sql='Thực thi truy vấn SQL')=>[m(3,4,query),m(4,5,sql),r(5,4,'Kết quả dữ liệu'),r(4,3,result)];
const save=(t='Lưu thay đổi',method='SaveChangesAsync()')=>[m(3,4,method),m(4,5,t),r(5,4,'Thực hiện thành công'),r(4,3,'Kết quả thực hiện')];
const tx=()=>save('BEGIN TRANSACTION','BeginTransactionAsync()');
const commit=()=>save('COMMIT','CommitAsync()');
const finish=(t='Kết quả xử lý',status='200 OK + ApiResponse')=>[r(3,2,t),r(2,1,status),r(1,0,'Hiển thị kết quả')];
const begin=(action,route,method)=>[m(0,1,action),m(1,2,route),m(2,3,method)];
const guard=(t,msg='Ngoại lệ nghiệp vụ')=>[start('break',t),...finish(msg,'Phản hồi lỗi qua pipeline'),end()];
function add(g,title,ui,ctrl,service,pre,events,desc='',sources=[]){scenarios.push({group:g,title,ui,ctrl,service,pre,events,desc,sources,actor:g>=18&&g<=27?'Quản trị viên':'Khách hàng'});return scenarios.at(-1);}
function view(g,title,ui,ctrl,service,method,query,pre='Người dùng được phép truy cập chức năng.',desc='',paged=false){let reads=paged&&method.includes('/')?[start('alt','Xem danh sách'),c('Chuẩn hóa trang và bộ lọc'),...db('CountAsync()','Tổng số bản ghi'),...db('Lấy trang dữ liệu theo bộ lọc'),other('Xem chi tiết theo id'),...db(query),end()]:[...(paged?[c('Chuẩn hóa trang và bộ lọc'),...db('CountAsync()','Tổng số bản ghi')]:[]),...db(query)];return add(g,title,ui,ctrl,service,pre,[...begin('Mở danh sách / chi tiết','GET dữ liệu',method),...reads,c('Ánh xạ dữ liệu sang DTO'),...finish('DTO / danh sách kết quả')],desc,[service,method]);}
function write(g,title,ui,ctrl,service,method,query,checks,change,desc='',opts={}){return add(g,title,ui,ctrl,service,opts.pre||'Đã đăng nhập và có quyền đối với dữ liệu.',[...begin('Nhập dữ liệu và xác nhận',opts.route||'Gửi yêu cầu cập nhật',method),...(opts.transaction?tx():[]),...db(query),c(checks),...guard('Dữ liệu / điều kiện không hợp lệ'),c(change),...save(opts.sql||'Lưu các bản ghi thay đổi'),...(opts.after||[]),...(opts.transaction?commit():[]),...(opts.reread?db('Đọc lại chi tiết sau xử lý','DTO chi tiết'):[]),...finish(opts.result||'Kết quả xử lý',opts.status||'200 OK + ApiResponse')],desc,[service,method]);}

// 01: architectural interaction, deliberately identified as a generic view.
add(1,'Luồng xử lý một yêu cầu nghiệp vụ','Giao diện Angular','Controller tương ứng','Service tương ứng','Sơ đồ kiến trúc tổng quát; tên lớp cụ thể được xác định ở các sơ đồ chức năng.',[...begin('Chọn chức năng','HTTP request','Gọi phương thức Service'),...db('Truy vấn qua AppDbContext'),c('Thực hiện quy tắc nghiệp vụ'),start('opt','Chức năng cần ghi dữ liệu'),...save(),end(),...finish('DTO kết quả')],'Pipeline kiểm tra xác thực, phân quyền và dữ liệu đầu vào trước nghiệp vụ. ExceptionMiddleware chuyển ngoại lệ thành phản hồi lỗi. Các yêu cầu công khai không bắt buộc đăng nhập.').actor='Người dùng';

// Authentication and sessions. Shared service interactions are explicitly referenced.
add(2,'Đăng ký tài khoản','RegisterComponent','AuthController','AuthService','Chưa có tài khoản; dữ liệu hợp lệ.',[m(0,1,'Nhập thông tin đăng ký'),m(1,2,'POST /api/auth/register'),ref('28. Kiểm tra CAPTCHA trước khi gọi AuthService'),m(2,3,'RegisterAsync(dto)'),...db('AnyAsync(email); lấy role Customer','Email và vai trò'),...guard('Email trùng / thiếu role Customer'),c('Chuẩn hóa email; băm BCrypt; tạo User và UserRole'),...save('INSERT User và UserRole'),c('CreateAuthResponse(): gọi TokenService.CreateToken'),r(3,2,'AuthResponseDto'),ref('7a. AuthController gọi RefreshTokenService.IssueAsync; đặt cookie HttpOnly'),r(2,1,'201 Created + ApiResponse'),r(1,0,'Thiết lập phiên đăng nhập')],'Kiểm tra trùng email gồm kiểm tra trước khi lưu và xử lý vi phạm chỉ mục unique khi có yêu cầu đồng thời. CAPTCHA của đăng ký chặn cả trường hợp dịch vụ xác minh không khả dụng.',['AuthService','RegisterAsync']);
add(3,'Đăng nhập tài khoản','LoginComponent','AuthController','AuthService','Có tài khoản.',[m(0,1,'Nhập email và mật khẩu'),m(1,2,'POST /api/auth/login'),ref('28. Kiểm tra CAPTCHA trước bước tra tài khoản'),m(2,3,'LoginAsync(dto, ip)'),...db('Tìm User kèm UserRoles và Role','User hoặc không có'),c('Kiểm tra khóa tạm, BCrypt và IsActive'),start('break','Không hợp lệ'),start('opt','Sai mật khẩu; User tồn tại và chưa khóa'),c('AccountLockout.RegisterFailure'),...save('Lưu bộ đếm sai / khóa tạm'),end(),...finish('UnauthorizedException','401 Unauthorized'),end(),start('alt','TwoFactorEnabled = true'),ref('4a. TwoFactorService.CreateLoginChallengeAsync; lưu challenge'),r(3,2,'LoginResult có Challenge'),r(2,1,'requiresTwoFactor; chưa cấp phiên'),r(1,0,'Hiện ô nhập mã xác minh'),other('Không bật xác thực hai lớp'),c('Reset bộ đếm sai nếu cần'),start('opt','Có bộ đếm / khóa cũ cần reset'),...save('Lưu trạng thái đăng nhập'),end(),c('CreateAuthResponse(): TokenService tạo JWT'),r(3,2,'LoginResult có AuthResponseDto'),ref('7a. Hoàn tất phiên và cấp refresh cookie'),r(2,1,'200 OK; phiên đăng nhập'),r(1,0,'Điều hướng sau đăng nhập'),end()],'Mật khẩu đúng chưa đủ để cấp JWT khi tài khoản bật 2FA. Không reset bộ đếm thất bại ở bước mật khẩu của tài khoản bật 2FA.',['AuthService','LoginAsync']);
add(4,'Tạo challenge đăng nhập hai lớp','LoginComponent','AuthController','TwoFactorService','AuthService xác nhận mật khẩu đúng và tài khoản bật 2FA.',[ref('AuthService gọi CreateLoginChallengeAsync(userId, ip)'),m(2,3,'CreateLoginChallengeAsync(...)'),c('Sinh token ngẫu nhiên; băm token; đặt thời hạn'),...save('INSERT TwoFactorChallenge'),r(3,2,'TwoFactorChallengeDto qua AuthService'),r(2,1,'requiresTwoFactor + challenge'),r(1,0,'Yêu cầu mã xác minh')],'Lời gọi Service được thực hiện bên trong AuthService.LoginAsync; sơ đồ này tách riêng tương tác tạo challenge. Token thô trả cho giao diện; cơ sở dữ liệu chỉ giữ hash.',['TwoFactorService','CreateLoginChallengeAsync']);
add(4,'Xác minh TOTP hoặc mã khôi phục','LoginComponent','AuthController','TwoFactorService','Đang có challenge đăng nhập.',[...begin('Nhập mã xác minh','POST two-factor/verify hoặc recovery','VerifyLoginCodeAsync / VerifyLoginRecoveryCodeAsync'),...db('Đọc challenge theo hash kèm User','Challenge và tài khoản'),c('Kiểm tra hạn, đã dùng, IsActive, 2FA và khóa'),...guard('Challenge sai / hết hạn / tài khoản bị khóa','TwoFactorLoginResult thất bại'),...save('Giữ chỗ lượt thử bằng UPDATE có điều kiện','ExecuteUpdateAsync()'),c('Xác minh TOTP hoặc hash mã khôi phục; chống dùng lại'),start('break','Mã sai / mã bị dùng lại / hết lượt'),c('Ghi thất bại và xét khóa tài khoản'),...save('Lưu trạng thái thất bại'),...finish('Kết quả thất bại có reason','401 Unauthorized'),end(),ref('Tiêu thụ challenge / mã bằng cập nhật có điều kiện; reset lỗi trong giao dịch'),r(3,2,'TwoFactorLoginResult thành công'),ref('AuthController gọi AuthService.CreateAuthResponseForUserAsync; TokenService tạo JWT'),ref('7a. Cấp refresh cookie sau xác minh đầy đủ'),r(2,1,'200 OK + AuthResponseDto'),r(1,0,'Đăng nhập thành công')],'TOTP cũ không được dùng lại; mã khôi phục dùng một lần. Các cập nhật xác minh thành công phải thắng kiểm tra cạnh tranh trong TwoFactorService.',['TwoFactorService','VerifyLoginCodeAsync']);
add(5,'Quên mật khẩu','ForgotPasswordComponent','AuthController','AuthService','Người dùng nhập email.',[...begin('Gửi email quên mật khẩu','POST /api/auth/forgot-password','ForgotPasswordAsync(dto)'),...db('Tìm User theo email','User hoặc không có'),start('opt','Tài khoản tồn tại và đang hoạt động'),c('Sinh reset token; hạn 30 phút'),...save('Lưu token và thời hạn'),ref('AuthService gọi EmailService.SendAsync để gửi liên kết'),end(),...finish('Đã tiếp nhận yêu cầu')],'Phản hồi giống nhau khi email không tồn tại. Lỗi gửi email được ghi log và không làm lộ tài khoản.',['AuthService','ForgotPasswordAsync']);
add(6,'Đặt lại mật khẩu','ResetPasswordComponent','AuthController','AuthService','Có reset token và mật khẩu mới.',[...begin('Xác nhận mật khẩu mới','POST /api/auth/reset-password','ResetPasswordAsync(dto)'),...db('Tìm User theo reset token','User và thời hạn'),...guard('Token không có / hết hạn'),c('Băm mật khẩu; xóa reset token'),...tx(),...save('Lưu mật khẩu mới và xóa token'),ref('RefreshTokenService.RevokeAllForUserAsync trong cùng giao dịch'),...commit(),...finish('Đặt lại thành công')],'Token chỉ dùng một lần. Lưu mật khẩu và thu hồi refresh token nằm trong cùng giao dịch; người dùng đăng nhập lại.',['AuthService','ResetPasswordAsync']);
add(7,'Cấp refresh token khi hoàn tất đăng nhập','LoginComponent / RegisterComponent','AuthController','RefreshTokenService','Đã có AuthResponseDto hợp lệ sau đăng ký, đăng nhập hoặc xác minh 2FA.',[ref('Tiếp sau AuthService trả AuthResponseDto'),m(2,3,'IssueAsync(userId, ip, userAgent)'),c('Sinh raw token, hash và họ phiên'),...save('INSERT RefreshToken'),r(3,2,'IssuedRefreshToken'),m(2,2,'SetRefreshTokenCookie: HttpOnly'),r(2,1,'JWT trong body; refresh token trong cookie'),r(1,0,'Thiết lập trạng thái phiên')],'CompleteSignInAsync thu hồi họ refresh token cũ của trình duyệt khi áp dụng, sau đó cấp cookie mới. Raw refresh token không nằm trong JSON.',['RefreshTokenService','IssueAsync']);
add(7,'Làm mới phiên đăng nhập','Giao diện Angular','AuthController','RefreshTokenService','Trình duyệt tự gửi refresh cookie.',[...begin('Khôi phục phiên / JWT hết hạn','POST /api/auth/refresh','RotateAsync(cookie, ip, userAgent)'),...db('Tìm token kèm User và họ phiên','Trạng thái phiên'),c('Kiểm tra hạn, thu hồi, User và tái sử dụng token'),...guard('Phiên không hợp lệ','RefreshRotationResult thất bại'),ref('RotateAsync xoay vòng token bằng cập nhật có điều kiện và giao dịch'),r(3,2,'UserId và token mới'),ref('AuthService.CreateAuthResponseForUserAsync: đọc User, tạo JWT qua TokenService'),m(2,2,'Đặt refresh cookie mới'),r(2,1,'200 OK + phiên mới'),r(1,0,'Cập nhật access token')],'Refresh lỗi trả 401. Không xóa cookie khi kết quả là ConcurrentReuse để tránh phản hồi thua ghi đè cookie mới của yêu cầu thắng.',['RefreshTokenService','RotateAsync']);
add(7,'Đăng xuất','Giao diện Angular','AuthController','RefreshTokenService','Có hoặc đã từng có cookie phiên.',[...begin('Chọn đăng xuất','POST /api/auth/logout','RevokeFamilyAsync(cookie, reason)'),...db('Tìm họ token theo cookie','FamilyId hoặc không có'),start('opt','Tìm thấy họ phiên'),...save('Thu hồi các token trong họ','ExecuteUpdateAsync()'),end(),r(3,2,'Đã xử lý thu hồi'),m(2,2,'DeleteRefreshTokenCookie()'),r(2,1,'200 OK'),m(1,1,'Xóa JWT trong bộ nhớ và thông tin user'),r(1,0,'Về trạng thái chưa đăng nhập')],'Đăng xuất thu hồi họ refresh token và xóa cookie; cookie thiếu hoặc không hợp lệ vẫn được xử lý theo luồng logout.',['RefreshTokenService','RevokeFamilyAsync']);

