add(8,'Tìm kiếm sản phẩm theo từ khóa','ProductListComponent','ProductsController','StorefrontService','Tìm theo Keyword; Sort mặc định mới nhất; không chọn bộ lọc khác.',[...begin('Nhập từ khóa và tìm kiếm','GET /api/products','GetProductsAsync(query)'),c('Chuẩn hóa trang; lọc Keyword và IsActive; sắp xếp CreatedAt'),...db('CountAsync()','totalItems','Đếm sản phẩm phù hợp'),...db('Skip / Take / ToListAsync()','productList','Lấy trang; kèm danh mục, hãng, ảnh'),c('MapProductListDto; tính TotalPages'),...finish('PagedResult<PublicProductListDto>')],'Đây là luồng mẫu đã thống nhất: Controller và Service tách riêng, đọc dữ liệu qua AppDbContext và SQL Server. Danh sách rỗng vẫn là kết quả thành công.',['StorefrontService','GetProductsAsync']);
add(8,'Lọc sản phẩm theo danh mục và điều kiện','ProductListComponent','ProductsController','StorefrontService','Khách chọn danh mục, hãng, khoảng giá và thứ tự.',[...begin('Áp dụng bộ lọc','GET /api/products','GetProductsAsync(query)'),c('Chuẩn hóa Page và PageSize'),start('opt','Có CategoryId'),...db('GetActiveCategoryBranchIdsAsync: đọc các danh mục hoạt động','Các danh mục và quan hệ cha'),c('Lấy nhánh danh mục; ID không hợp lệ cho nhánh rỗng'),end(),c('Áp dụng Keyword, CategoryId, BrandId, Gender, giá và Sort'),...db('CountAsync()','Tổng số phù hợp'),...db('Skip / Take / ToListAsync()','Trang sản phẩm'),...finish('PagedResult')],'API hỗ trợ Gender; trang ProductList hiện bỏ tham số gender trên URL. Sort bestselling chỉ cộng số lượng bán trong đơn Completed.',['StorefrontService','GetProductsAsync']);
view(8,'Xem chi tiết sản phẩm','ProductDetailComponent','ProductsController','StorefrontService','GetProductBySlugAsync(slug)','Đọc Product theo slug; Include ảnh, biến thể, màu, size','Khách truy cập một sản phẩm.','Sản phẩm và danh mục phải đang hoạt động; không tìm thấy trả 404. Biến thể trả về phải IsActive. Đánh giá công khai được gọi qua endpoint Reviews riêng.');
view(8,'Sản phẩm nổi bật và mới nhất','HomeComponent','ProductsController','StorefrontService','GetFeaturedProductsAsync / GetNewArrivalProductsAsync','Lọc IsActive; sắp xếp CreatedAt; Take(limit)','Khách mở trang chủ.','Đây là hai yêu cầu độc lập: featured thêm IsFeatured; new-arrivals lấy sản phẩm mới. Service chuẩn hóa limit và ánh xạ DTO.');
view(8,'Sản phẩm liên quan','ProductDetailComponent','ProductsController','StorefrontService','GetRelatedProductsAsync(productId, limit)','Đọc sản phẩm hiện tại rồi lấy sản phẩm cùng danh mục','Khách mở chi tiết sản phẩm.','Loại sản phẩm hiện tại khỏi kết quả; chỉ lấy sản phẩm và danh mục đang hoạt động. Không có sản phẩm gốc thì trả 404.');

