write(9,'Xóa một dòng hoặc xóa giỏ','CartComponent','CartController','CartService','DeleteItemAsync / ClearCartAsync','Đọc dòng theo userId hoặc các dòng giỏ của user','Kiểm tra sở hữu; xóa dòng cần tồn tại; giỏ rỗng không cần lưu','Remove / RemoveRange CartItems','Không kiểm tra tồn kho và không yêu cầu sản phẩm còn kinh doanh. DeleteItemAsync không trả giỏ mới; giao diện tải lại khi cần.',{result:'Hoàn tất thao tác xóa'});
view(10,'Xem danh sách yêu thích','MyWishlistComponent','WishlistController','WishlistService','GetMyWishlistAsync(userId)','Truy vấn WishlistItems của user kèm thông tin sản phẩm','Khách hàng đã đăng nhập.');
